def clean(df):
    df = df.copy()
    # normalize text labels (strip whitespace, fix case)
    for c in ['Product', 'Category', 'Region']:
        if c in df.columns:
            df[c] = df[c].astype('string').str.strip().str.title()
    # drop exact duplicate rows
    df = df.drop_duplicates()
    # drop rows with invalid (negative) quantity
    df = df[df['Quantity'].isna() | (df['Quantity'] >= 1)]
    return df.reset_index(drop=True)

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category', 'Price'])
    g = d.groupby('Category')['Price'].mean()
    return {str(k): float(v) for k, v in g.items()}
